<?php
declare(strict_types=1); namespace BaktiRelease; function unpack(string $release, string $relative, string $iv, string $tag, string $payload): string { $keyDir = getenv('APP_RELEASE_KEY_DIR') ?: dirname(BAKTI_RELEASE_ROOT, 2) . '/.bakti-secrets'; $keyFile = $keyDir . '/' . $release . '.key.php'; if (!preg_match('/^[a-zA-Z0-9-]+$/', $release) || !is_file($keyFile) || !function_exists('openssl_decrypt')) { http_response_code(503); exit('Aplikasi sedang disiapkan. Silakan coba kembali.'); } $hex = require $keyFile; if (!is_string($hex) || !preg_match('/^[a-f0-9]{64}$/', $hex)) { http_response_code(503); exit('Konfigurasi build belum siap.'); } $code = openssl_decrypt(base64_decode($payload, true), 'aes-256-gcm', hex2bin($hex), OPENSSL_RAW_DATA, base64_decode($iv, true), base64_decode($tag, true), $release . ':' . $relative); if ($code === false) { error_log('Bakti: encrypted release authentication failed'); http_response_code(503); exit('Berkas aplikasi belum dapat diverifikasi.'); } if (strncmp($code, "BKT2\0", 5) === 0) { $code = function_exists('gzinflate') ? @gzinflate(substr($code, 5), 16777216) : false; if ($code === false) { error_log('Bakti: compressed release could not be decoded'); http_response_code(503); exit('Berkas aplikasi belum dapat dibuka.'); } } return $code; } 